"""Random 32-bit values, plus ones built from four visibly distinct bytes so
a byte landing in the wrong place cannot hide behind a repeated value."""


def generate(rng, count):
    builders = (_anything, _distinct_bytes, _one_byte_set)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, value, description=""):
    return {"name": name, "stdin": "%X\n" % value, "description": description}


def _anything(rng, index):
    return _case("a random value #%d" % index, rng.randrange(0, 2 ** 32))


def _distinct_bytes(rng, index):
    b = rng.sample(range(0, 256), 4)
    value = (b[0] << 24) | (b[1] << 16) | (b[2] << 8) | b[3]
    return _case("four distinct bytes #%d" % index, value,
                 "Every byte differs from the others, so a byte in the "
                 "wrong place cannot hide behind a repeat.")


def _one_byte_set(rng, index):
    byte = rng.randrange(1, 256)
    position = rng.randrange(4)
    value = byte << (position * 8)
    return _case("one byte set, the rest zero #%d" % index, value,
                 "Only byte %d is non-zero; it should land at byte %d." %
                 (position, 3 - position))
